import {openStudioDb,transact,requestResult} from '../../src/infrastructure/storage/database';
import {acquireProjectLease} from '../../src/infrastructure/storage/project-lease';
import {saveProject} from '../../src/infrastructure/storage/project-repository';
import {f} from '../helpers/fixtures';
const unknownRun={id:'future-run',projectId:'p1',taskId:'future-task',connectionId:'original-service',authBindingId:'original-binding',executionState:'future_pending',queryState:'future_tracking',deliveryState:'future_delivery',billingState:'reconcile_required',futureEvidence:{receipt:'local-fake-receipt',credits:'unknown'}};
const unknownPromptRun={id:'future-prompt',draftId:'d1',connectionId:'original-text-service',authBindingId:'original-binding',executionState:'future_response_unknown',billingState:'reconcile_required',futureEvidence:{requestId:'local-fake-request'}};
export async function snapshot(){const db=await openStudioDb();try{return await transact(db,['projects','graphs','runs','promptRuns'],'readonly',async tx=>({projects:await requestResult<Record<string,unknown>[]>(tx.objectStore('projects').getAll()),graphs:await requestResult<Record<string,unknown>[]>(tx.objectStore('graphs').getAll()),runs:await requestResult<Record<string,unknown>[]>(tx.objectStore('runs').getAll()),promptRuns:await requestResult<Record<string,unknown>[]>(tx.objectStore('promptRuns').getAll())}));}finally{db.close();}}
export async function prepareFutureProject(){const db=await openStudioDb();try{await transact(db,['projects','graphs','runs','promptRuns'],'readwrite',tx=>{tx.objectStore('projects').put({...f.project({revision:7}),schemaVersion:2,futureCreativeData:{unchanged:true}});tx.objectStore('graphs').put(f.graph({revision:7}));tx.objectStore('runs').put(unknownRun);tx.objectStore('promptRuns').put(unknownPromptRun);});}finally{db.close();}}
export async function staleOverwrite(){const db=await openStudioDb();try{await transact(db,['projects','graphs'],'readwrite',tx=>{tx.objectStore('projects').put(f.project({revision:7}));tx.objectStore('graphs').put(f.graph({revision:7}));});const lease=await acquireProjectLease('p1','old-bundle-tab',Date.now(),{db});if(!lease.ok)throw Error(lease.errorCode);await prepareFutureProject();const before=await snapshot(),result=await saveProject(f.project({revision:8,title:'旧版本覆写'}),7,{db,lease:lease.token,graph:f.graph({revision:8})}),after=await snapshot();return {before,result,after};}finally{db.close();}}
export async function upgradeAndRejectOldDatabase(){const name='aiwork-studio:release-rehearsal-'+crypto.randomUUID(),db=await openStudioDb({name});await transact(db,['runs','promptRuns'],'readwrite',tx=>{tx.objectStore('runs').put(unknownRun);tx.objectStore('promptRuns').put(unknownPromptRun);});db.close();const upgraded=await new Promise<IDBDatabase>((resolve,reject)=>{const r=indexedDB.open(name,3);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});upgraded.close();let error='';try{const old=await openStudioDb({name});old.close();}catch(e){error=e instanceof Error?e.message:'unknown';}const original=await new Promise<IDBDatabase>((resolve,reject)=>{const r=indexedDB.open(name);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});try{const tx=original.transaction(['runs','promptRuns'],'readonly');return {error,version:original.version,run:await requestResult(tx.objectStore('runs').get('future-run')),prompt:await requestResult(tx.objectStore('promptRuns').get('future-prompt'))};}finally{original.close();}}
